    expect($user->isSuperAdmin())->toBeTrue()
        ->and(driver()->override($user, projectScope(7)))->toBe(Effect::Allow);
});

it('defers when the real user is not a super-admin', function (): void {
    $user = realUser();
    bindRealAdapter($user);

